    private static async Task<List<object>> GetEopReasonByEmploymentTypeId(
        AppDbContext db, int? employmentTypeId, int agreementTypeId)
    {
        var reasons = await db.Set<EopReasonType>()
            .Where(r => r.EmploymentTypeId == employmentTypeId && r.AgreementTypeId == agreementTypeId)
            .Select(r => new { r.Id, r.Description })
            .Cast<object>()
            .ToListAsync();
        return reasons;
    }

    private static async Task<List<object>> GetEopReasonForExtension(AppDbContext db)
    {
