            .Where(r => r.ReasonType == "extension")
            .Select(r => new { r.Id, r.Description })
            .Cast<object>()
            .ToListAsync();
        return reasons;
    }

    private static async Task<List<object>> GetEopReasonForBenchPlacements(AppDbContext db)
    {
        var reasons = await db.Set<EopReasonType>()
            .Where(r => r.ReasonType == "bench")
            .Select(r => new { r.Id, r.Description })
            .Cast<object>()
            .ToListAsync();
        return reasons;
    }

    private static async Task<List<(string Code, string? Value)>> GetStatesList(
        AppDbContext db, bool param1, bool param2, bool selectOne, string[]? except = null)
    {
        var states = await db.Set<States>()
            .Where(s => except == null || !except.Contains(s.Description ?? ""))
            .Select(s => new { s.Code, s.Description })
            .ToListAsync();

        var result = new List<(string, string?)>();
        if (selectOne)
        {
            result.Add(("0", "-- Select One --"));
        }
        foreach (var s in states)
        {
            result.Add((s.Code ?? "", s.Description));
        }
        return result;
    }

