    private static async Task<List<EopProcessedDto>> GetEopHistoryByPlacementId(
        AppDbContext db, int placementId)
    {
        var history = await db.Set<EopProcessed>()
            .Where(e => e.ContractorPlacementId == placementId)
            .OrderByDescending(e => e.UpdateOn)
            .Select(e => new EopProcessedDto
            {
                UpdateOn = e.UpdateOn,
                ProposedDate = e.ProposedDate,
                EopStatusTypeId = e.EopStatusTypeId,
                EopWorkflowStatusId = e.EopWorkflowStatusId,
                Notes = e.Notes
            })
            .ToListAsync();
        return history;
    }

    private static DateTime ParseDisplayDate(string displayDate)
    {
        // Convert MM/DD/YYYY to DateTime
        if (DateTime.TryParseExact(displayDate, "MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture,
            System.Globalization.DateTimeStyles.None, out var result))
        {
            return result;
        }
        return new DateTime(2000, 1, 1);
    }

    private static string ToDisplayDate(DateTime? date)
    {
        return date?.ToString("MM/dd/yyyy") ?? "";
    }

    private static async Task<DateTime> GetPlacementStartDate(AppDbContext db, int placementId)
    {
        var placement = await db.Set<ContractorPlacement>().FindAsync(placementId);
        return placement?.StartDate ?? DateTime.MinValue;
    }

    private static async Task<DateTime> GetLastEnteredTsDate(AppDbContext db, int placementId)
    {
        var lastTs = await db.Set<Timesheet>()
            .Where(t => t.ContractorPlacementId == placementId)
            .OrderByDescending(t => t.EnteredDate)
            .Select(t => t.EnteredDate)
            .FirstOrDefaultAsync();
        return lastTs ?? DateTime.MinValue;
    }

    private static async Task<int> GetEopWorkflowStatusId(AppDbContext db, string statusName)
    {
        var status = await db.Set<EopWorkflowStatusType>()
            .Where(s => s.Description == statusName)
            .Select(s => s.Id)
            .FirstOrDefaultAsync();
        return status;
    }

    private static async Task<int> GetEopStatusTypeId(AppDbContext db, string statusName)
    {
        var status = await db.Set<EopStatusType>()
            .Where(s => s.Description == statusName)
            .Select(s => s.Id)
            .FirstOrDefaultAsync();
        return status;
    }

    private static async Task<decimal> GetMinimumBenchPayRate(
        AppDbContext db, string zip, string stateId, DateTime startDate, int payRateId)
    {
        var minRate = await db.Set<OnbMinimumPayStateMap>()
            .Where(m => m.Zip == zip && m.StateId == stateId && m.EffectiveDate <= startDate)
            .OrderByDescending(m => m.EffectiveDate)
            .Select(m => m.MinimumRate)
            .FirstOrDefaultAsync();
        return minRate ?? 0m;
    }

    private static async Task<int> GetCustomerClientPartnerId(AppDbContext db, int customerId)
    {
        var customer = await db.Set<Customer>().FindAsync(customerId);
        return customer?.ClientPartnerId ?? 1;
    }
